// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette{value: 10 ether}(); }
    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(c) && actor != address(0));
        vm.assume(amount <= type(uint128).max);
        vm.roll(1); // block.number % 15 != 0: no refund path
        vm.deal(actor, amount);
        uint256 balBefore = address(c).balance;
        vm.prank(actor);
        (bool ok,) = address(c).call{value: amount}("");
        assertTrue(!ok || address(c).balance == balBefore + 10 ether);
    }
}
